export const ASCENDED_FORMS={legendary:{attack:'蒼穹曜翼獅鷲',magic:'霜月九尾靈狐',defense:'琥珀山脈晶犀',support:'聖光星冠獨角獸'},mythic:{attack:'赤曜裂界龍皇',magic:'星焰輪迴神凰',defense:'終界玄岩泰坦',support:'太初玉麟聖君'}};
export const ASCENSION_COST={ascend:{essence_4:30,ascension_core:10},mutate:{essence_4:50,ascension_core:20}};
export const ASCENSION_MULTIPLIERS={common:100,rare:50,uncommon:10,legendary:1,mythic:1};
export const LOYALTY_MAX=500,LOYALTY_PER_POINT=100,ASCENSION_LOYALTY=100;
export const petLevelCap=(pet,ownerReborn=false)=>pet.ascended||ownerReborn?150:99;
export function ascensionCost(pet,mode='ascend'){const base=ASCENSION_COST[mode],factor=mode==='ascend'?ASCENSION_MULTIPLIERS[pet?.rarity]:1;return base&&factor?Object.fromEntries(Object.entries(base).map(([id,n])=>[id,n*factor])):null;}
function loyaltyState(pet){const old=Math.max(0,Math.floor(Number(pet.loyalty)||0));if(pet.loyaltyVersion!==2)return {loyalty:Math.min(LOYALTY_MAX,old),loyaltyKills:0,loyaltyVersion:2};const loyalty=Math.min(LOYALTY_MAX,old);return {loyalty,loyaltyKills:loyalty===LOYALTY_MAX?0:Math.max(0,Math.min(LOYALTY_PER_POINT-1,Math.floor(Number(pet.loyaltyKills)||0))),loyaltyVersion:2};}
export function normalizeLoyalty(pet){Object.assign(pet,loyaltyState(pet));return pet;}
export function ascensionError(pet,bag,location,mode='ascend'){if(!['town','skycity'].includes(location))return '請回村莊進行界限進化';if(!pet||!Object.hasOwn(ASCENSION_MULTIPLIERS,pet.rarity))return '寵物品質無效';if(pet.level<99||pet.evolution<4)return '需要99級且完成四次一般進化';if(mode==='ascend'&&pet.ascended)return '已完成界限進化';if(mode==='mutate'&&(!pet.ascended||pet.rarity!=='legendary'))return '異化僅適用界限傳說寵物';const cost=ascensionCost(pet,mode);if(!cost)return '無效進化方式';if(mode==='ascend'&&loyaltyState(pet).loyalty<ASCENSION_LOYALTY)return '需要忠誠度100（界限進化時消耗）';return Object.entries(cost).some(([id,n])=>(bag.find(e=>e.id===id)?.qty||0)<n)?'進化素材不足':null;}
export function ascendPet(pet,bag,location,mode='ascend',rng=Math.random){const error=ascensionError(pet,bag,location,mode);if(error)return {error};const before=pet.rarity,cost=ascensionCost(pet,mode);normalizeLoyalty(pet);for(const [id,n] of Object.entries(cost))bag.find(e=>e.id===id).qty-=n;for(let i=bag.length-1;i>=0;i--)if(!bag[i].uid&&bag[i].qty===0)bag.splice(i,1);if(mode==='ascend'){pet.loyalty-=ASCENSION_LOYALTY;pet.ascended=true;if(before!=='mythic')pet.rarity='legendary';return {before,after:pet.rarity,mutation:false,guaranteedLegend:before!=='mythic',ascended:true};}const mutation=rng()<.15;if(mutation)pet.rarity='mythic';return {before,after:pet.rarity,mutation,ascended:true};}
export function awardLoyalty(pet,monsterLevel){if(!pet||pet.hp<=0||Math.abs(pet.level-monsterLevel)>40)return 0;normalizeLoyalty(pet);if(pet.loyalty>=LOYALTY_MAX)return 0;pet.loyaltyKills++;if(pet.loyaltyKills<LOYALTY_PER_POINT)return 0;pet.loyaltyKills=0;pet.loyalty++;return 1;}
